import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.DTdEDYjJ.js";const A=JSON.parse('{"title":"Bot 协作与通信边界","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/bot-communication.md","filePath":"concepts/bot-communication.md"}'),d={name:"concepts/bot-communication.md"};function n(p,t,i,h,c,l){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="bot-协作与通信边界" tabindex="-1">Bot 协作与通信边界 <a class="header-anchor" href="#bot-协作与通信边界" aria-label="Permalink to &quot;Bot 协作与通信边界&quot;">​</a></h1><p>本文记录 2026-10-20 确定的通信架构约定。内部接口与自建 Node 接口已有实现；<strong>不同账号之间的 A2A Adapter 尚未实现或通过互通验收</strong>。本文不表示统一账号登录、自动发现或跨账号组网已经接通。</p><h2 id="两条约定" tabindex="-1">两条约定 <a class="header-anchor" href="#两条约定" aria-label="Permalink to &quot;两条约定&quot;">​</a></h2><ol><li><strong>OpenBot 内部使用内部函数接口。</strong> Bot 派单、结果读取与取消由宿主服务管理，各 Bot 使用自己的 Harness。桌面界面通过 Electron IPC 调用宿主；不为每个 Bot 启动独立网络服务。</li><li><strong>不同账号的独立 OpenBot，单独设置 A2A Adapter。</strong> 外部协议由 Adapter 映射到内部 Bot 接口，接收方继续负责执行权限、状态与责任记录。此 Adapter 属于待开发能力。</li></ol><p>B2B（Bot-to-Bot）是 OpenBot 的 Bot 协作数据模型，用来表达长期身份、职责、派单与责任归属；不再另外设计一套 B2B 网络协议。</p><h2 id="当前使用哪一种接口" tabindex="-1">当前使用哪一种接口 <a class="header-anchor" href="#当前使用哪一种接口" aria-label="Permalink to &quot;当前使用哪一种接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>通信边界</th><th>接口</th><th>状态</th></tr></thead><tbody><tr><td>Mac 界面 → 本机宿主</td><td>Electron IPC</td><td>已有</td></tr><tr><td>同一 OpenBot 内的 Bot 协作</td><td>内部函数接口与各自 Harness</td><td>已有，执行范围见<a href="/openbot/guide/jarvis.html">主脑与任务委派</a></td></tr><tr><td>客户端 → 自己的 Node</td><td>HTTP(S) JSON、Bearer 令牌与游标事件轮询</td><td>已有，见 <a href="/openbot/reference/node-api.html">Node API</a></td></tr><tr><td>不同账号的独立 OpenBot</td><td>独立 A2A Adapter → 内部 Bot 接口</td><td>待开发与互通验收</td></tr></tbody></table><p>边界按所属系统和账号划分，不只看机器数量。Mac 连接自己部署的 Node，继续使用现有节点接口；换一台机器安装 OpenBot，不会自动发现、连接或同步其他安装。现有 Node 接口也不应称为 A2A。</p><h2 id="a2a-adapter-负责什么" tabindex="-1">A2A Adapter 负责什么 <a class="header-anchor" href="#a2a-adapter-负责什么" aria-label="Permalink to &quot;A2A Adapter 负责什么&quot;">​</a></h2><p>拟议 Adapter 只处理外部互通：认证、能力暴露、协议映射、请求关联、取消和结果返回。具体映射计划如下，当前不能作为可调用 API 使用。</p><table tabindex="0"><thead><tr><th>A2A 对象或操作</th><th>拟映射的 OpenBot 概念</th></tr></thead><tbody><tr><td>Agent Card</td><td>对外公开且允许访问的 Bot 能力描述</td></tr><tr><td>Message</td><td>发给指定 Bot 的请求或回复</td></tr><tr><td>Task</td><td>内部任务实例及其实际状态</td></tr><tr><td>Artifact</td><td>明确允许返回的产物</td></tr><tr><td>取消请求</td><td>内部停止接口及其实际执行结果</td></tr></tbody></table><p>消息、任务、Agent Card、产物与取消机制以 <a href="https://a2a-protocol.org/latest/specification/" target="_blank" rel="noreferrer">A2A 官方规范</a> 为准。实现时需要锁定规范和 SDK 版本，验证状态、重复请求、取消与失败处理；规范支持某项机制，不代表 OpenBot 已实现对应 Adapter。</p><h2 id="权限与上下文的边界" tabindex="-1">权限与上下文的边界 <a class="header-anchor" href="#权限与上下文的边界" aria-label="Permalink to &quot;权限与上下文的边界&quot;">​</a></h2><p>接收方必须根据经过验证的认证信息识别调用者，再检查允许访问的 Bot、能力和操作。对方自报的 Bot ID、领导角色或 <code>contextId</code> 只用于描述与关联，不能自行授予权限。</p><p>内部服务保留 Bot 身份、职责、模型与 Harness 绑定、任务范围、授权与审计。跨系统只传递明确授权的输入与结果，不自动带出私人记忆、其他空间聊天、模型订阅、API Key 或浏览器登录状态。把一次请求关联到已有上下文，也不能绕过原有的账号和记忆边界。</p><p>账号在这里表示所有者的信任边界，不等于同名 Bot、同一模型配置或同一 IP。账号登录、Node 连接和数据同步是分别实现与验收的能力，见<a href="/openbot/concepts/architecture.html">身份、执行与连接</a>及<a href="/openbot/deployment/network.html">连接与网络</a>。</p><h2 id="开发与验收约定" tabindex="-1">开发与验收约定 <a class="header-anchor" href="#开发与验收约定" aria-label="Permalink to &quot;开发与验收约定&quot;">​</a></h2><p>内部调用继续复用宿主函数接口，不为兼容外部系统而改写整个执行内核。A2A Adapter 独立适配这些接口，并在交付时分别记录认证、权限、取消、请求去重、重启后状态和互通结果。</p><p>这次架构决定同时记入<a href="/openbot/development/changelog.html#communication-decision-20261020">开发者变更记录</a>。在 Adapter 完成并有实际验收证据之前，文档、界面与 Agent 能力描述均须保留“待开发”状态。</p>',19)])])}const b=e(d,[["render",n]]);export{A as __pageData,b as default};
